import { createContext, useContext } from "solid-js";
import { createMutable } from "solid-js/store";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { getModifierTextByContext } from "#core/ui/utilities/utilities-core-textprovider.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

import { TraditionDisplayItem } from "#base/ui/policies/model-government.js";

export interface GovtScreenChooserModel {
	choicesAvailable: GovtChoiceItem[];
	currentlySelectedChoice: GovernmentType | null;
	onCardClick: (governmentType: GovernmentType) => void;
	onConfirmClicked: () => void;
	onCloseClicked: () => void;
}

export interface GovtChoiceItem {
	governmentName: string;
	governmentPassive?: string;
	celebrationItems: GovtDisplayItem[];
	governmentType: GovernmentType;
	traditionsUnlocked: TraditionDisplayItem[];
}

interface GovtDisplayItem {
	itemName?: string;
	image: string;
	description: string;
}

export function createGovtChooserModel() {
	const governmentChoices: GovtChoiceItem[] = [];
	let traditionsUnlocked: TraditionDisplayItem[] = [];
	let celebrationChoices: GovtDisplayItem[] = [];
	const localPlayerID: PlayerId = GameContext.localPlayerID;
	let govAbility: string | undefined = undefined;

	const player: PlayerLibrary | null = Players.get(localPlayerID);
	if (player) {
		if (player.Culture) {
			const playerHappiness: PlayerHappiness | undefined = player.Happiness;
			if (playerHappiness) {
				const goldenAgeDuration: number = playerHappiness.getGoldenAgeDuration();

				//create a button for each government that we can choose from
				for (const startingGovernmentDef of GameInfo.StartingGovernments) {
					const governmentType: GovernmentType = startingGovernmentDef.GovernmentType;
					const governmentDef: GovernmentDefinition | null = GameInfo.Governments.lookup(governmentType);
					if (governmentDef) {
						const govModifiers = GameInfo.GovernmentModifiers.filter(
							(m) => m.GovernmentType === governmentType,
						);
						for (const govMod of govModifiers) {
							const text = getModifierTextByContext(govMod.ModifierId, "Description");
							if (text) {
								govAbility = text;
								break;
							}
						}

						traditionsUnlocked = [];
						const lookupGov = GameInfo.Governments.lookup(governmentType)?.GovernmentType;
						const govTypeString: string = lookupGov ?? "";
						let unlockNode: ProgressionTreeNodeUnlockDefinition[] = [];

						const govtNodes: ProgressionTreeNodeUnlockDefinition[] =
							GameInfo.ProgressionTreeNodeUnlocks.filter(
								(o) => o.RequiredGovernmentType == govTypeString,
							);
						if (govtNodes) {
							if (govtNodes.length > 0) {
								for (const govtTraditions in govtNodes) {
									const tradition = GameInfo.Traditions.lookup(govtNodes[govtTraditions].TargetType);
									if (tradition) {
										unlockNode = govtNodes.filter(
											(item) => item.TargetType == govtNodes[govtTraditions].TargetType,
										);
										const nodeObject = GameInfo.ProgressionTreeNodes.lookup(
											unlockNode[0].ProgressionTreeNodeType,
										);
										const unlockNodeName = nodeObject ? nodeObject.Name : "";
										const traditionDisplayItem: TraditionDisplayItem = {
											def: tradition,
											unlock: `{LOC_LOADING_TRADITION_UNLOCKED_WITH} [B]{${unlockNodeName}}[/B]`,
										};
										traditionsUnlocked.push(traditionDisplayItem);
									}
								}
							}
						}

						const governmentCelebrationTypes: string[] = Game.Culture.GetCelebrationTypesForGovernment(
							governmentDef.GovernmentType,
						);

						celebrationChoices = [];
						for (const celebrationChoice of governmentCelebrationTypes) {
							const celebrationItemDef: GoldenAgeDefinition | null =
								GameInfo.GoldenAges.lookup(celebrationChoice);
							if (celebrationItemDef) {
								const newItem: GovtDisplayItem = {
									itemName: celebrationItemDef.Name,
									image: `url(${UI.getIconURL(celebrationItemDef.GoldenAgeType)})`,
									description: Locale.stylize(celebrationItemDef.Description, goldenAgeDuration),
								};
								celebrationChoices.push(newItem);
							}
						}
						const governmentChoice: GovtChoiceItem = {
							governmentName: governmentDef.Name,
							celebrationItems: celebrationChoices,
							governmentType: governmentDef.GovernmentType,
							governmentPassive: govAbility,
							traditionsUnlocked: traditionsUnlocked,
						};
						governmentChoices.push(governmentChoice);
					}
				}
			}
		}
	}

	function onClose() {
		ContextManager.pop("screen-government-chooser");
	}

	function handleCardClicked(governmentType: GovernmentType) {
		model.currentlySelectedChoice = governmentType;
	}

	function onConfirm() {
		if (!model.currentlySelectedChoice) {
			console.error(
				"screen-government-chooser: confirmChooseGovernment() - no government choice currently selected!",
			);
			return;
		}
		const governmentType: GovernmentType = model.currentlySelectedChoice;
		if (governmentType) {
			const governmentDef: GovernmentDefinition | null = GameInfo.Governments.lookup(governmentType);
			if (!governmentDef) {
				console.error(
					`screen-government-chooser: confirmChooseGovernment() - no government def found for government type ${governmentType}`,
				);
				return;
			}

			const args = {
				GovernmentType: governmentDef.$index,
				Action: PlayerOperationParameters.Activate,
			};
			const result = Game.PlayerOperations.canStart(
				GameContext.localPlayerID,
				PlayerOperationTypes.CHANGE_GOVERNMENT,
				args,
				false,
			);
			if (result.Success) {
				Game.PlayerOperations.sendRequest(
					GameContext.localPlayerID,
					PlayerOperationTypes.CHANGE_GOVERNMENT,
					args,
				);
				model.onCloseClicked();
			}
		}
	}

	const model = createMutable<GovtScreenChooserModel>({
		choicesAvailable: governmentChoices,
		onConfirmClicked: onConfirm,
		onCardClick: handleCardClicked,
		onCloseClicked: onClose,
		currentlySelectedChoice: null,
	});

	return model;
}

//#region model registry / init
export const GovtChooserModel = ModelRegistry.register(
	"GovtScreenModel",
	ModelLifecycle.SharedInstance,
	createGovtChooserModel,
);

export const GovtChooserModelContext = createContext<GovtScreenChooserModel>();

export function useGovtChooserModelContext() {
	const context = useContext(GovtChooserModelContext);

	if (!context) {
		throw new Error("useGovtChooserModelContext: Cannot find context!");
	}

	return context;
}
